import {completedPhotoDay} from '../hosted/photo-completion.mjs';
import {createHash} from 'node:crypto';import {photoCaseReviewed} from './photo-review-guard.mjs';
const sha=x=>createHash('sha256').update(x).digest('hex'),hex=x=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x);
export function chooseLegacyProposal(a,b){const rank={unavailable:0,pending:1,stale:2,submitted:3,needs_recovery:4,proposed:5,needs_review:6,retained:7};return (rank[b?.status]??0)>(rank[a?.status]??0)?b:a;}
function indexInventory(inv){const byKey=new Map(),q=inv.queue;for(const item of q.items){const day=item.scopeDate||item.recordKey.slice(0,10);if(item.duplicateOf||q.scope&&(day<q.scope.from||day>q.scope.to))continue;for(const key of new Set([item.recordKey,item.datedRecordKey].filter(Boolean))){const list=byKey.get(key)||[];list.push(item);byKey.set(key,list);}}return {inv,byKey};}
function inventoryStatus(row,{inv,byKey}){if(completedPhotoDay(row,inv.queue.completedReportDays))return 'retained';const candidates=byKey.get(row.key)||[];if(!candidates.length)return 'unavailable';const d=row.delivery||{},url=sha(d.photo_url),clock=String(d.raw_upload||d.upload||null),matching=candidates.filter(x=>x.urlSha256===url&&String(x.proofTimestamp??null)===clock&&(!d.photo_sha256||!x.imageSha256||d.photo_sha256===x.imageSha256));if(!matching.length)return 'stale';for(const c of matching){const f=inv.flags?.[c.id];if(f)return f.id===c.id&&f.status==='needs_review'&&typeof f.reason==='string'&&f.reason.length<=2000&&typeof f.flaggedAt==='string'&&f.flaggedAt.length<=100?'needsReview':'stale';}for(const c of matching){const p=inv.proposals?.[c.id];if(!p)continue;if(p.id!==c.id||p.recordKey!==c.recordKey||p.urlSha256!==url||String(p.proofTimestamp??null)!==clock||p.status!=='proposed'||!hex(p.imageSha256)||p.rubricVersion!==inv.queue.rubricVersion||p.reviewerModel!=='gpt-6.1-terra'||!Number.isInteger(p.grade)||p.grade<0||p.grade>3||typeof p.reason!=='string'||p.reason.length>2000||typeof p.uncertainty!=='string'||p.uncertainty.length>2000||typeof p.reviewedAt!=='string'||p.reviewedAt.length>100||c.cachedSha256!=null&&c.cachedSha256!==p.imageSha256||d.photo_sha256&&d.photo_sha256!==p.imageSha256)return 'stale';return 'proposed';}if(matching.some(c=>inv.attempts?.[c.id]))return matching.some(c=>inv.attempts?.[c.id]?.status==='submitted')?'submitted':'needsRecovery';if(matching.some(c=>inv.unavailable?.[c.id]))return 'unavailable';return 'pending';}
// `cloud` contains only immutable, digest-verified results with exact current
// image/URL/clock binding. One dated record contributes at most once.
export function currentPhotoProgress({rows,inventories,cloud=new Map(),journal,verifiedSourceOnlyImages=new Set()}){if(!Array.isArray(rows)||!Array.isArray(inventories)||inventories.length!==2||!(cloud instanceof Map)||!(verifiedSourceOnlyImages instanceof Set))throw Error('Invalid photo progress population');const idx=inventories.map(indexInventory),counts={total:0,proposed:0,needsReview:0,needsRecovery:0,submitted:0,unavailable:0,pending:0,stale:0,retained:0,activeWorkers:0},keys=new Set(),blockedKeys=new Set(),completedDays=new Set();for(const inv of inventories){for(const day of inv.queue.completedReportDays||[])completedDays.add(day);for(const item of inv.queue.items)if(inv.proposals?.[item.id]||inv.flags?.[item.id]||inv.attempts?.[item.id]){if(item.recordKey)blockedKeys.add(item.recordKey);if(item.datedRecordKey)blockedKeys.add(item.datedRecordKey);}}for(const row of rows){if(!row?.key||keys.has(row.key))throw Error('Ambiguous photo record');keys.add(row.key);if(!row.delivery?.photo_url)continue;const [a,b]=idx.map(x=>inventoryStatus(row,x));const rank={unavailable:0,pending:1,stale:2,submitted:3,needsRecovery:4,proposed:5,needsReview:6,retained:7};let status=rank[b]>rank[a]?b:a;const hasCandidates=idx.some(x=>x.byKey.has(row.key)),blocked=photoCaseReviewed(row,journal)||(completedPhotoDay(row,completedDays)||blockedKeys.has(row.key));const overlay=cloud.get(row.key);if(overlay&&!blocked&&['pending','unavailable'].includes(status))status=overlay.status==='needs_review'?'needsReview':'proposed';else if(!hasCandidates&&(!overlay||blocked)){ if(photoCaseReviewed(row,journal)||completedPhotoDay(row,completedDays))status='retained';else status=hex(row.delivery.photo_sha256)?'pending':'unavailable';}if(row.sourceOnly?.assessmentState==='unavailable'&&(!hex(row.delivery?.photo_sha256)||!verifiedSourceOnlyImages.has(row.key))&&['pending','unavailable','proposed'].includes(status))status='unavailable';counts.total++;counts[status]++;}return counts;}
